export default async function Dashboard() {
  let analytics, notifications, settings

  try {
    ;[analytics, notifications, settings] = await Promise.all([
      fetch('/api/analytics').then((r) => r.json()),
      fetch('/api/notifications').then((r) => r.json()),
      fetch('/api/settings').then((r) => r.json()),
    ])
  } catch {
    analytics = { views: 0, visits: 0 }
    notifications = []
    settings = {}
  }

  return (
    <div>
      <h2>Dashboard Content</h2>
      <pre>{JSON.stringify({ analytics, notifications, settings }, null, 2)}</pre>
    </div>
  )
}

